/* Integration tests: plans generated by AegisPlan (Module 1) and converted by aegis/aegisplan/export_viz.py load,
   path-find and simulate in this engine. Regenerate the fixtures with `python scripts/export_viz_fixtures.py` in aegis/. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import * as E from '../../src/engine';
import type { PlanJson, Scenario } from '../../src/engine';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const dir = path.join(root, 'tests/fixtures/aegis');
const read = (f: string): unknown => JSON.parse(fs.readFileSync(path.join(root, f), 'utf8'));
const fixtures = fs.readdirSync(dir).filter(f => f.endsWith('.plan.json'));
const scn = read('samples/scenarios/normal-tuesday.scenario.json') as Scenario;

describe('AegisPlan fixtures', () => {
  it('there are fixtures to test', () => expect(fixtures.length).toBeGreaterThan(0));

  for (const f of fixtures)
    it(f + ': loads with its own doors, reaches every room and runs a day', () => {
      const json = read(path.join('tests/fixtures/aegis', f)) as PlanJson;
      const P = E.preparePlan(json, []);

      expect(P.m.inferredDoors).toBe(false);
      expect(P.m.doors.some(d => d.id === 'entrance')).toBe(false);
      expect(P.m.doors.filter(d => d.isEntrance).length).toBeGreaterThan(0);
      expect(P.info.unreachableRooms).toEqual([]);
      expect(P.info.allExams.length).toBe(P.m.rooms.filter(r => r.type === 'exam_room').length);
      expect(E.runChecks(P).every(c => c.pass)).toBe(true);

      const day = E.runDay(P, E.compileScenario(scn), 99);
      expect(day.seen).toBeGreaterThan(0);
      expect(day.unreachable).toBe(0);
    });
});
